INSTRUCTIONS = '# msft-deck\n\nProduce a .pptx that survives Kody\'s review on the first pass. The historical failure modes this skill exists to kill, in order of how often they burned turns: handing over a deck with a broken/ugly slide he had to screenshot back, overwriting slides he authored, walls of text, delivering HTML when he wanted pptx, and asking him to open/check things you can check yourself.\n\n## Mode detection (do this first)\n\n1. **REVISE** — he gave you a deck he (or a customer) touched: make ONLY the changes he asked for, in place, with python-pptx. Never regenerate, reorder, or "improve" other slides. His words: "keep the slides I had... THATS IT". When in doubt whether a slide is his, it\'s his.\n2. **RESTYLE** — he gave a deck and wants it in the house style: keep content and slide order exactly; change fonts, colors, spacing, layout polish only.\n3. **NEW** — build from notes/transcript/md/conversation. Distill the BUSINESS USE CASE, not the conversation that produced it. A transcript is raw ore, never an outline.\n\n## Style contract (extracted from the canonical STYLED reference deck)\n\n- 16:9 (13.33in x 7.5in). Build with python-pptx (installed, v1.0.2).\n- Fonts: **Segoe UI** body, **Segoe UI Semibold** headings/emphasis, Consolas for code. Never Calibri, never the template default.\n- Palette: text `#1B1A19` (near-black) and `#3B3A39`; secondary text `#605E5C`; accent/link **`#0078D4`** (Microsoft blue); positive `#107C10`; warning/highlight `#D83B01`; white `#FFFFFF` on dark fills. Nothing outside this palette without being asked.\n- Type scale: titles ~40pt, section heads ~19pt, body 13–14pt, captions 10.5–12pt.\n- Layout: generous whitespace, left-aligned text, consistent margins across ALL slides (misaligned elements = "looks vibe coded"). One visual anchor per slide max.\n\n## Content rules (KISS — he has said this five times in a row)\n\n- Default ≤ 10 slides. One idea per slide. ≤ 5 bullets per slide, ≤ 12 words per bullet. If a slide needs a paragraph, it\'s two slides or a talk track.\n- Customer-facing decks: **strip PII** — no customer employee names, emails, or internal identifiers unless he explicitly says otherwise. Generalize ("a national retailer") if the customer name itself is sensitive.\n- Output is a real `.pptx` on disk. HTML decks only when he asks for HTML. Never emojis.\n\n## Self-review gate (non-negotiable — this is the whole point)\n\nBefore telling him anything is done:\n\n1. Render: `soffice --headless --convert-to pdf --outdir <dir> <deck>.pptx`\n2. **Read the PDF and look at every page.** Check each slide for: text overflowing or clipped by shapes, overlapping elements, off-palette colors, wrong/default fonts, ragged alignment vs neighboring slides, orphaned placeholder text ("Click to add..."), unreadable contrast.\n3. Fix everything you find, re-render, re-inspect. Loop until a full pass is clean. Do not ask him to be the QA loop — no screenshots from him, ever.\n4. In REVISE mode, additionally diff-check: confirm untouched slides are byte-identical in content (same text runs) to what he gave you.\n\n## Handoff\n\n- Save next to the source (or `~/Desktop` for ad-hoc asks), versioned `Name_v2.pptx` style if a prior version exists — never overwrite the file he gave you.\n- Pop it open: `open -a "Microsoft PowerPoint" <deck>.pptx`\n- Report: file path, slide count, one line per change made (REVISE/RESTYLE) or the slide-by-slide outline (NEW), and confirmation the visual pass was clean.'

# Ordered commands lifted verbatim from the capability's own documentation.
STEPS = [
    {
        "cmd": "open -a \"Microsoft PowerPoint\" <deck>.pptx",
        "line": 37
    }
]


class MsftDeckAgent(BasicAgent):
    def __init__(self):
        self.name = 'MsftDeck'
        self.metadata = {
        "name": "MsftDeck",
        "description": "Build, restyle, or revise a PowerPoint deck in Kody's Microsoft styling, self-review every slide visually, and only hand it over verified and popped open. Use whenever the user asks for a deck, slides, a pptx, a one-pager deck, to \"restyle\" a deck, to make slides \"look like the STYLED one\" / \"not look vibe coded\", or to turn notes/a transcript/an md into a presentation.",
        "parameters": {
                "properties": {
                        "deck": {
                                "description": "Derived from `<deck>` used in the documented command at line 29.",
                                "type": "string"
                        }
                },
                "required": [],
                "type": "object"
        }
        }
        super().__init__(name=self.name, metadata=self.metadata)

    def perform(self, **kwargs):  # toaster:generated-perform
        missing = [k for k in self.metadata["parameters"].get("required", [])
                   if k not in kwargs]
        if missing:
            return json.dumps({"status": "error",
                               "missing_required": missing}, indent=2)
        resolved, unresolved = [], set()
        for step in STEPS:
            cmd = step["cmd"]
            for key, value in kwargs.items():
                for token in ("<" + key.replace("_", "-") + ">",
                              "<" + key + ">",
                              "{{" + key + "}}",
                              "$" + key.upper()):
                    cmd = cmd.replace(token, str(value))
            for leftover in re.findall(r"<[a-zA-Z][a-zA-Z0-9 _.-]{1,40}>", cmd):
                unresolved.add(leftover)
            resolved.append(cmd)
        return json.dumps({"status": "ok",
                           "steps": resolved,
                           "unresolved_placeholders": sorted(unresolved),
                           "note": "Resolved deterministically by the agent; "
                                   "run in order. Nothing was executed here."},
                          indent=2)

